function ProjectsIndexInner() {
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<string | undefined>(undefined);
  const [search, setSearch] = useState("");
  const q = useDebounced(search);
  const [filters, setFilters] = useState<{ status?: string }>({});
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const setFilter = (key: keyof typeof filters, value: string) => {
    setFilters(current => ({ ...current, [key]: value }));
    setPage(1);
  };
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const could = fieldsOf(session.data).projects;
  const { tenant, loading: tenantLoading } = useTenant();
  const input = {
    page,
    page_size: PAGE_SIZE,
    sort,
    q: q || undefined,
    status: filters.status || undefined,
    ...fixedFilter(user, tenant)
  } as Inputs["projects"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.projects.list(input), enabled: tenant !== null });
  const router = useRouter();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0 flex-col">
      <PaneHeader title="Projects" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/projects/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New project">
              <Plus />
            </Link>
          ) : null}
      </PaneHeader>


      <div className="flex flex-wrap items-center gap-2 border-b border-border px-4 py-2">
          <Input type="search" placeholder="Search" className="w-56" value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} />
          <select aria-label="Status" className={selectClass + " w-auto"} value={filters.status ?? ""} onChange={e => setFilter("status", e.target.value)}>
            <option value="">Status: any</option>
            <option value="active">active</option>
            <option value="archived">archived</option>
          </select>
      </div>
      <div className="min-h-0 flex-1 overflow-auto px-4">
        {!tenantLoading && tenant === null ? (
          <NoTenant />
        ) : list.isPending ? (
          <ListSkeleton />
        ) : list.error ? (
          <ErrorNote error={list.error} className="m-4" />
        ) : list.data.data.length === 0 ? (
          <EmptyPane>No projects found.</EmptyPane>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>
                  <SortHeader field="name" sort={sort} onSort={next => { setSort(next); setPage(1); }}>
                    Name
                  </SortHeader>
                </TableHead>
                <TableHead>Status</TableHead>
                {could.budget ? <TableHead>Budget</TableHead> : null}
                <TableHead>
                  <SortHeader field="created_at" sort={sort} onSort={next => { setSort(next); setPage(1); }}>
                    Created At
                  </SortHeader>
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {list.data.data.map((row: Row) => (
                <TableRow key={text(row.id)} className="cursor-pointer" onClick={() => router.push(`/projects/${text(row.id)}`)}>
                  <TableCell>{text(row.name)}</TableCell>
                  <TableCell>{text(row.status)}</TableCell>
                  {could.budget ? <TableCell>{text(row.budget)}</TableCell> : null}
                  <TableCell>{formatDateTime(row.created_at)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
      {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
    </div>
  );
}

function ProjectsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { tenant, loading: tenantLoading } = useTenant();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.projects.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/projects/${text(row.id)}`);
    }
  });
  // A field with a read rule is offered only to a viewer who could read it, and is not sent otherwise
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const could: Record<string, boolean> = fieldsOf(session.data).projects;
  const readable = (field: string) => could[field] === true;
  if (tenantLoading) return <PaneSkeleton />;
  if (tenant === null) return <NoTenant />;
  return (
    <Pane title="New project" actions={<Link href="/projects" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <ProjectsForm
        fields={offeredProjects(PROJECTS_CREATE, readable)}
        initial={EMPTY_PROJECTS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate({ ...sentProjects(toProjectsCreateInput(values), readable), team_id: tenant?.id } as Input<"create">)}
      />
    </Pane>
  );
}

function ProjectsDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.projects.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["projects"]["update"]) => client.projects.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["projects"]["delete"]) => client.projects.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/projects");
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <RowError error={query.error} signIn={<Link href="/login" className={buttonVariants()}>Sign in</Link>} />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Project " + text(row.id)}
      actions={
        <>
          <Link href="/projects" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this project?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <ProjectsForm
          fields={offeredProjects(PROJECTS_UPDATE, field => field in row)}
          initial={projectsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: sentProjects(toProjectsUpdateInput(values), field => field in row) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Team">{user !== null ? <Link href={`/teams/${text(row.team_id)}`} className="hover:underline">{text(row.team_id) || "—"}</Link> : text(row.team_id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Status">{row.status == null ? "—" : <Badge variant="secondary">{text(row.status)}</Badge>}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Public">{row.public == null ? "—" : <Badge variant={row.public ? "default" : "outline"}>{yesNo(row.public)}</Badge>}</FieldRow>
        <FieldRow label="Milestone Count">{text(row.milestone_count) || "—"}</FieldRow>
        <FieldRow label="Open Milestones">{text(row.open_milestones) || "—"}</FieldRow>
        {"budget" in row ? (
          <FieldRow label="Budget">{text(row.budget) || "—"}</FieldRow>
        ) : null}
        </dl>
      )}
    </Pane>
  );
}

